style.css:
/* Pink background */
html, body, ytmusic-app {
    background-color: #F5DADF !important;
}

/* Pink sidebar */
ytmusic-pivot-bar-renderer {
    background-color: #D99AA5 !important;
}

/* Pink buttons & player */
ytmusic-player-bar {
    background-color: #D99AA5 !important;
}

/* Make text cute */
yt-formatted-string, span, a {
    color: #F5DADF !important;
    font-family: "Comic Sans MS", cursive !important; /* Optional: cutesy font! */
}
